void TrajectoryRanker::process(const CandidateTrajectories::ConstSharedPtr msg)
{
  autoware_utils_debug::ScopedTimeTrack st(__func__, *time_keeper_);
  pub_trajectories_->publish(*score(msg));
}

ScoredCandidateTrajectories::ConstSharedPtr TrajectoryRanker::score(
  const CandidateTrajectories::ConstSharedPtr msg)
{
  autoware_utils_debug::ScopedTimeTrack st(__func__, *time_keeper_);

  ScoredCandidateTrajectories output;
  output.generator_info = msg->generator_info;

  if (!route_handler_->isHandlerReady()) {
    RCLCPP_WARN_THROTTLE(
      get_logger(), *get_clock(), 5000, "Route handler is not ready. Returning empty output.");
    return std::make_shared<ScoredCandidateTrajectories>(output);
  }

  const auto odometry_ptr = std::const_pointer_cast<Odometry>(sub_odometry_.take_data());
  if (odometry_ptr == nullptr) {
    RCLCPP_WARN_THROTTLE(
      get_logger(), *get_clock(), 5000, "Odometry data is not available. Returning empty output.");
    return std::make_shared<ScoredCandidateTrajectories>(output);
  }

  const auto objects_ptr = std::const_pointer_cast<PredictedObjects>(sub_objects_.take_data());
  if (objects_ptr == nullptr) {
    RCLCPP_WARN_THROTTLE(
      get_logger(), *get_clock(), 5000, "Objects data is not available. Returning empty output.");
    return std::make_shared<ScoredCandidateTrajectories>(output);
  }

  const auto preferred_lanes =
    std::make_shared<lanelet::ConstLanelets>(route_handler_->getPreferredLanelets());

  std::vector<autoware_internal_planning_msgs::msg::ScoredCandidateTrajectory> trajectories;
  trajectories.reserve(msg->candidate_trajectories.size());

  evaluator_->clear();

  const auto params = parameters();

  // Process each candidate trajectory
  for (const auto & candidate : msg->candidate_trajectories) {
    auto sampled = utils::sampling(
      candidate.points, odometry_ptr->pose.pose, params->sample_num, params->resolution);
    auto sampled_points = std::make_shared<TrajectoryPoints>(std::move(sampled));
    auto original_points = std::make_shared<TrajectoryPoints>(candidate.points);

    // Create shared pointer to trajectory history for passing to CoreData
    auto trajectory_history_ptr = std::make_shared<std::deque<Trajectory>>(trajectory_history_);

    auto core_data = std::make_shared<CoreData>(
      original_points, sampled_points, previous_points_, objects_ptr, preferred_lanes,
      candidate.header, candidate.generator_id, trajectory_history_ptr);

    evaluator_->add(core_data);
  }

  const auto best_data = evaluator_->best(params);
  previous_points_ = best_data == nullptr ? nullptr : best_data->points();

  // Update trajectory history buffer with the best trajectory
  if (best_data != nullptr && best_data->points() != nullptr) {
    // Create Trajectory from best trajectory
    Trajectory best_trajectory;
    best_trajectory.header = best_data->header();
    best_trajectory.points = *best_data->original();

    trajectory_history_.push_back(best_trajectory);

    // Limit buffer size
    if (trajectory_history_.size() > max_history_size_) {
      trajectory_history_.pop_front();
    }
  }

  for (const auto & result : evaluator_->results()) {
    const auto candidate = autoware_internal_planning_msgs::build<
                             autoware_internal_planning_msgs::msg::CandidateTrajectory>()
                             .header(result->header())
                             .generator_id(result->uuid())
                             .points(*result->original());
    const auto scored_trajectory =
      autoware_internal_planning_msgs::build<
        autoware_internal_planning_msgs::msg::ScoredCandidateTrajectory>()
        .candidate_trajectory(candidate)
        .score(result->total());
    trajectories.push_back(scored_trajectory);
  }

  output.scored_candidate_trajectories = trajectories;
  return std::make_shared<ScoredCandidateTrajectories>(output);
}

bool RouteHandler::isHandlerReady() const
{
  return is_handler_ready_;
}

TrajectoryPoints sampling(
  const TrajectoryPoints & points, const Pose & p_ego, const size_t sample_num,
  const double resolution)
{
  TrajectoryPoints output;
  if (points.empty() || sample_num == 0) return output;

  const auto ego_idx_opt = autoware::motion_utils::findNearestIndex(points, p_ego, 10.0, M_PI_2);

  if (!ego_idx_opt.has_value()) return output;
  const size_t ego_idx = std::min(ego_idx_opt.value(), points.size() - 1);

  // time vector
  std::vector<double> times;
  times.reserve(points.size());
  for (const auto & pt : points) times.push_back(to_seconds(pt.time_from_start));

  const double t0 = times[ego_idx];
  output.reserve(sample_num);

  for (size_t i = 0; i < sample_num; i++) {
    const double elapsed_time = t0 + static_cast<double>(i) * resolution;
    const auto seg_opt = find_segment_index(times, elapsed_time, ego_idx);
    if (!seg_opt.has_value()) {
      output.push_back(points.back());
      continue;
    }
    const size_t index = seg_opt.value();
    const double t1 = times[index];
    const double t2 = times[index + 1];

    if (t2 == t1) {
      output.push_back(points.at(index));
      continue;
    }

    const double ratio = (elapsed_time - t1) / (t2 - t1);
    output.push_back(calc_interpolated_point(points.at(index), points.at(index + 1), ratio, false));
  }
  return output;
}

std::optional<size_t> findNearestIndex(
  const T & points, const geometry_msgs::msg::Pose & pose,
  const double max_dist = std::numeric_limits<double>::max(),
  const double max_yaw = std::numeric_limits<double>::max())
{
  try {
    validateNonEmpty(points);
  } catch (const std::exception & e) {
    RCLCPP_DEBUG(get_logger(), "%s", e.what());
    return {};
  }

  const double max_squared_dist = max_dist * max_dist;

  double min_squared_dist = std::numeric_limits<double>::max();
  bool is_nearest_found = false;
  size_t min_idx = 0;

  for (size_t i = 0; i < points.size(); ++i) {
    const auto squared_dist = autoware_utils_geometry::calc_squared_distance2d(points.at(i), pose);
    if (squared_dist > max_squared_dist || squared_dist >= min_squared_dist) {
      continue;
    }

    const auto yaw = autoware_utils_geometry::calc_yaw_deviation(
      autoware_utils_geometry::get_pose(points.at(i)), pose);
    if (std::fabs(yaw) > max_yaw) {
      continue;
    }

    min_squared_dist = squared_dist;
    min_idx = i;
    is_nearest_found = true;
  }

  if (is_nearest_found) {
    return min_idx;
  }
  return std::nullopt;
}

double calc_squared_distance2d(const Point1 & point1, const Point2 & point2)
{
  const auto p1 = get_point(point1);
  const auto p2 = get_point(point2);
  const auto dx = p1.x - p2.x;
  const auto dy = p1.y - p2.y;
  return dx * dx + dy * dy;
}

geometry_msgs::msg::Point get_point(const T & p)
{
  return geometry_msgs::build<geometry_msgs::msg::Point>().x(p.x).y(p.y).z(p.z);
}

double calc_yaw_deviation(
  const geometry_msgs::msg::Pose & base_pose, const geometry_msgs::msg::Pose & target_pose)
{
  const auto base_yaw = tf2::getYaw(base_pose.orientation);
  const auto target_yaw = tf2::getYaw(target_pose.orientation);
  return autoware_utils_math::normalize_radian(target_yaw - base_yaw);
}

inline double normalize_radian(const double rad, const double min_rad = -pi)
{
  const auto max_rad = min_rad + 2 * pi;

  const auto value = std::fmod(rad, 2 * pi);
  if (min_rad <= value && value < max_rad) {
    return value;
  }

  return value - std::copysign(2 * pi, value);
}

geometry_msgs::msg::Pose get_pose([[maybe_unused]] const T & p)
{
  static_assert(sizeof(T) == 0, "Only specializations of get_pose can be used.");
  throw std::logic_error("Only specializations of get_pose can be used.");
}

std::optional<size_t> find_segment_index(
  const std::vector<double> & times, double t, size_t start_index)
{
  if (times.size() < 2) return std::nullopt;
  const size_t start = std::min(start_index, times.size() - 1);

  if (t < times.front()) return std::nullopt;
  if (t >= times.back()) return std::nullopt;

  auto it = std::upper_bound(times.begin() + start, times.end(), t);

  if (it == times.begin() || it == times.end()) return std::nullopt;
  return static_cast<size_t>(std::distance(times.begin(), it)) - 1;
}

TrajectoryPoint calc_interpolated_point(
  const TrajectoryPoint & curr_pt, const TrajectoryPoint & next_pt, const double ratio,
  const bool use_zero_order_hold_for_twist)
{
  const double clamped_ratio = std::clamp(ratio, 0.0, 1.0);
  TrajectoryPoint interpolated_point{};

  // pose interpolation
  interpolated_point.pose =
    autoware_utils_geometry::calc_interpolated_pose(curr_pt, next_pt, ratio);

  // twist interpolation
  if (use_zero_order_hold_for_twist) {
    interpolated_point.longitudinal_velocity_mps = curr_pt.longitudinal_velocity_mps;
    interpolated_point.lateral_velocity_mps = curr_pt.lateral_velocity_mps;
    interpolated_point.acceleration_mps2 = curr_pt.acceleration_mps2;
  } else {
    interpolated_point.longitudinal_velocity_mps = autoware::interpolation::lerp(
      curr_pt.longitudinal_velocity_mps, next_pt.longitudinal_velocity_mps, clamped_ratio);
    interpolated_point.lateral_velocity_mps = autoware::interpolation::lerp(
      curr_pt.lateral_velocity_mps, next_pt.lateral_velocity_mps, clamped_ratio);
    interpolated_point.acceleration_mps2 = autoware::interpolation::lerp(
      curr_pt.acceleration_mps2, next_pt.acceleration_mps2, clamped_ratio);
  }

  // heading rate interpolation
  interpolated_point.heading_rate_rps = autoware::interpolation::lerp(
    curr_pt.heading_rate_rps, next_pt.heading_rate_rps, clamped_ratio);

  // wheel interpolation
  interpolated_point.front_wheel_angle_rad = autoware::interpolation::lerp(
    curr_pt.front_wheel_angle_rad, next_pt.front_wheel_angle_rad, clamped_ratio);
  interpolated_point.rear_wheel_angle_rad = autoware::interpolation::lerp(
    curr_pt.rear_wheel_angle_rad, next_pt.rear_wheel_angle_rad, clamped_ratio);

  // time interpolation
  const double t1 = to_seconds(curr_pt.time_from_start);
  const double t2 = to_seconds(next_pt.time_from_start);
  const double t = (t2 == t1) ? t1 : autoware::interpolation::lerp(t1, t2, clamped_ratio);
  interpolated_point.time_from_start = rclcpp::Duration::from_seconds(t);

  return interpolated_point;
}

geometry_msgs::msg::Pose calc_interpolated_pose(
  const Pose1 & src_pose, const Pose2 & dst_pose, const double ratio,
  const bool set_orientation_from_position_direction = true)
{
  const double clamped_ratio = std::clamp(ratio, 0.0, 1.0);

  geometry_msgs::msg::Pose output_pose;
  output_pose.position =
    calc_interpolated_point(get_point(src_pose), get_point(dst_pose), clamped_ratio);

  if (set_orientation_from_position_direction) {
    const double input_poses_dist = calc_distance2d(get_point(src_pose), get_point(dst_pose));
    const bool is_driving_forward_flag = is_driving_forward(src_pose, dst_pose);

    // Get orientation from interpolated point and src_pose
    if ((is_driving_forward_flag && clamped_ratio > 1.0 - (1e-6)) || input_poses_dist < 1e-3) {
      output_pose.orientation = get_pose(dst_pose).orientation;
    } else if (!is_driving_forward_flag && clamped_ratio < 1e-6) {
      output_pose.orientation = get_pose(src_pose).orientation;
    } else {
      const auto & base_pose = is_driving_forward_flag ? dst_pose : src_pose;
      const double pitch = calc_elevation_angle(get_point(output_pose), get_point(base_pose));
      const double yaw = calc_azimuth_angle(get_point(output_pose), get_point(base_pose));
      output_pose.orientation = create_quaternion_from_rpy(0.0, pitch, yaw);
    }
  } else {
    // Get orientation by spherical linear interpolation
    tf2::Transform src_tf;
    tf2::Transform dst_tf;
    tf2::fromMsg(get_pose(src_pose), src_tf);
    tf2::fromMsg(get_pose(dst_pose), dst_tf);
    const auto & quaternion = tf2::slerp(src_tf.getRotation(), dst_tf.getRotation(), clamped_ratio);
    output_pose.orientation = tf2::toMsg(quaternion);
  }

  return output_pose;
}

