}

bool is_driving_forward(const Pose1 & src_pose, const Pose2 & dst_pose)
{
  // check the first point direction
  const double src_yaw = tf2::getYaw(get_pose(src_pose).orientation);
  const double pose_direction_yaw = calc_azimuth_angle(get_point(src_pose), get_point(dst_pose));
  return std::fabs(normalize_radian(src_yaw - pose_direction_yaw)) < pi / 2.0;
}

double calc_azimuth_angle(
  const geometry_msgs::msg::Point & p_from, const geometry_msgs::msg::Point & p_to)
{
  const double dx = p_to.x - p_from.x;
  const double dy = p_to.y - p_from.y;
  return std::atan2(dy, dx);
}

geometry_msgs::msg::Quaternion create_quaternion_from_rpy(
  const double roll, const double pitch, const double yaw)
{
  tf2::Quaternion q;
  q.setRPY(roll, pitch, yaw);
  return tf2::toMsg(q);
}

double lerp(const double src_val, const double dst_val, const double ratio)
{
  return src_val + (dst_val - src_val) * ratio;
}

void Evaluator::add(const std::shared_ptr<CoreData> & core_data)
{
  const auto ptr = std::make_shared<DataInterface>(core_data, plugins_.size());
  results_.push_back(ptr);
}

std::shared_ptr<DataInterface> Evaluator::best(
  const std::shared_ptr<EvaluatorParameters> & parameters, const std::string & exclude)
{
  evaluate(parameters->metrics_max_value);

  compress(parameters->time_decay_weight);

  normalize(parameters->time_decay_weight);

  weighting(parameters->score_weight);

  return best(exclude);
}

void SteeringConsistency::evaluate(
  const std::shared_ptr<autoware::trajectory_ranker::DataInterface> & result,
  const float max_value) const
{
  if (result->previous() == nullptr) return;
  if (!result->points() || result->points()->size() < 2) return;

  constexpr float epsilon = 1.0e-3f;
  std::vector<float> steering_command(result->points()->size(), 0.0f);
  if (max_value < epsilon) {
    result->set_metric(index(), steering_command);
    return;
  }

  const auto wheel_base = vehicle_info()->wheel_base_m;
  for (size_t i = 0; i < result->points()->size(); i++) {
    const auto & point = result->points()->at(i);
    const auto current = utils::steer_command(result->points(), point.pose, wheel_base);
    const auto previous = utils::steer_command(result->previous(), point.pose, wheel_base);

    steering_command.at(i) =
      std::min(1.0f, static_cast<float>(std::abs(current - previous)) / max_value);
  }

  result->set_metric(index(), steering_command);
}

float steer_command(
  const std::shared_ptr<TrajectoryPoints> & points, const Pose & ego_pose, const float wheel_base)
{
  return std::atan(wheel_base * pure_pursuit(points, ego_pose));
}

float pure_pursuit(const std::shared_ptr<TrajectoryPoints> & points, const Pose & ego_pose)
{
  if (!points || points->empty()) {
    return 0.0f;
  }

  const auto target_point = [&points, ego_pose]() {
    constexpr float lookahead_distance = 10.0f;
    const auto p = autoware::motion_utils::calcLongitudinalOffsetPoint(
      *points, ego_pose.position, lookahead_distance);

    if (p.has_value()) return p.value();

    return autoware_utils_geometry::get_point(points->back());
  }();

  return curvature(target_point, ego_pose);
}

std::optional<geometry_msgs::msg::Point> calcLongitudinalOffsetPoint(
  const T & points, const geometry_msgs::msg::Point & src_point, const double offset)
{
  try {
    validateNonEmpty(points);
  } catch (const std::exception & e) {
    RCLCPP_DEBUG(get_logger(), "Failed to calculate longitudinal offset: %s", e.what());
    return {};
  }

  if (offset < 0.0) {
    auto reverse_points = points;
    std::reverse(reverse_points.begin(), reverse_points.end());
    return calcLongitudinalOffsetPoint(reverse_points, src_point, -offset);
  }

  const size_t src_seg_idx = findNearestSegmentIndex(points, src_point);
  const double signed_length_src_offset =
    calcLongitudinalOffsetToSegment(points, src_seg_idx, src_point);

  return calcLongitudinalOffsetPoint(points, src_seg_idx, offset + signed_length_src_offset);
}

std::optional<geometry_msgs::msg::Point> calcLongitudinalOffsetPoint(
  const T & points, const size_t src_idx, const double offset, const bool throw_exception = false)
{
  try {
    validateNonEmpty(points);
  } catch (const std::exception & e) {
    RCLCPP_DEBUG(get_logger(), "%s", e.what());
    return {};
  }

  if (points.size() - 1 < src_idx) {
    const std::string error_message(
      "[autoware_motion_utils] " + std::string(__func__) +
      " error: The given source index is out of the points size. Failed to calculate longitudinal "
      "offset.");
    autoware_utils_system::print_backtrace();
    if (throw_exception) {
      throw std::out_of_range(error_message);
    }
    RCLCPP_DEBUG(
      get_logger(),
      "%s Return NaN since no_throw option is enabled. The maintainer must check the code.",
      error_message.c_str());
    return {};
  }

  if (points.size() == 1) {
    return {};
  }

  if (src_idx + 1 == points.size() && offset == 0.0) {
    return autoware_utils_geometry::get_point(points.at(src_idx));
  }

  if (offset < 0.0) {
    auto reverse_points = points;
    std::reverse(reverse_points.begin(), reverse_points.end());
    return calcLongitudinalOffsetPoint(
      reverse_points, reverse_points.size() - src_idx - 1, -offset);
  }

  double dist_sum = 0.0;

  for (size_t i = src_idx; i < points.size() - 1; ++i) {
    const auto & p_front = points.at(i);
    const auto & p_back = points.at(i + 1);

    const auto dist_segment = autoware_utils_geometry::calc_distance2d(p_front, p_back);
    dist_sum += dist_segment;

    const auto dist_res = offset - dist_sum;
    if (dist_res <= 0.0) {
      return autoware_utils_geometry::calc_interpolated_point(
        p_back, p_front, std::abs(dist_res / dist_segment));
    }
  }

  // not found (out of range)
  return {};
}

std::optional<geometry_msgs::msg::Point> calcLongitudinalOffsetPoint(
  const T & points, const size_t src_idx, const double offset, const bool throw_exception = false)
{
  try {
    validateNonEmpty(points);
  } catch (const std::exception & e) {
    RCLCPP_DEBUG(get_logger(), "%s", e.what());
    return {};
  }

  if (points.size() - 1 < src_idx) {
    const std::string error_message(
      "[autoware_motion_utils] " + std::string(__func__) +
      " error: The given source index is out of the points size. Failed to calculate longitudinal "
      "offset.");
    autoware_utils_system::print_backtrace();
    if (throw_exception) {
      throw std::out_of_range(error_message);
    }
    RCLCPP_DEBUG(
      get_logger(),
      "%s Return NaN since no_throw option is enabled. The maintainer must check the code.",
      error_message.c_str());
    return {};
  }

  if (points.size() == 1) {
    return {};
  }

  if (src_idx + 1 == points.size() && offset == 0.0) {
    return autoware_utils_geometry::get_point(points.at(src_idx));
  }

  if (offset < 0.0) {
    auto reverse_points = points;
    std::reverse(reverse_points.begin(), reverse_points.end());
    return calcLongitudinalOffsetPoint(
      reverse_points, reverse_points.size() - src_idx - 1, -offset);
  }

  double dist_sum = 0.0;

  for (size_t i = src_idx; i < points.size() - 1; ++i) {
    const auto & p_front = points.at(i);
    const auto & p_back = points.at(i + 1);

    const auto dist_segment = autoware_utils_geometry::calc_distance2d(p_front, p_back);
    dist_sum += dist_segment;

    const auto dist_res = offset - dist_sum;
    if (dist_res <= 0.0) {
      return autoware_utils_geometry::calc_interpolated_point(
        p_back, p_front, std::abs(dist_res / dist_segment));
    }
  }

  // not found (out of range)
  return {};
}

double calc_distance2d(const Point1 & point1, const Point2 & point2)
{
  const auto p1 = get_point(point1);
  const auto p2 = get_point(point2);
  return std::hypot(p1.x - p2.x, p1.y - p2.y);
}

geometry_msgs::msg::Point get_point(const T & p)
{
  return geometry_msgs::build<geometry_msgs::msg::Point>().x(p.x).y(p.y).z(p.z);
}

geometry_msgs::msg::Point calc_interpolated_point(
  const Point1 & src, const Point2 & dst, const double ratio)
{
  const auto src_point = get_point(src);
  const auto dst_point = get_point(dst);

  tf2::Vector3 src_vec;
  src_vec.setX(src_point.x);
  src_vec.setY(src_point.y);
  src_vec.setZ(src_point.z);

  tf2::Vector3 dst_vec;
  dst_vec.setX(dst_point.x);
  dst_vec.setY(dst_point.y);
  dst_vec.setZ(dst_point.z);

  // Get pose by linear interpolation
  const double clamped_ratio = std::clamp(ratio, 0.0, 1.0);
  const auto & vec = tf2::lerp(src_vec, dst_vec, clamped_ratio);

  geometry_msgs::msg::Point point;
  point.x = vec.x();
  point.y = vec.y();
  point.z = vec.z();

  return point;
}

